{
  "findings": [
    {
      "check_id": "CKV_AWS_88",
      "title": "EC2 instances receive public IP addresses",
      "resource": "aws_launch_configuration.lc",
      "severity": "HIGH",
      "explanation": "The launch configuration explicitly assigns public IP addresses to instances, unnecessarily exposing them to internet-routable traffic subject to the associated security group."
    },
    {
      "check_id": "CKV_AWS_79",
      "title": "IMDSv2 is not enforced",
      "resource": "aws_launch_configuration.lc",
      "severity": "HIGH",
      "explanation": "No metadata options require IMDSv2, allowing instances to use the less secure IMDSv1 protocol and increasing the risk of credential theft through metadata-service attacks."
    },
    {
      "check_id": "CKV_AWS_8",
      "title": "Root EBS volume encryption is not enforced",
      "resource": "aws_launch_configuration.lc",
      "severity": "HIGH",
      "explanation": "The launch configuration does not explicitly encrypt the instance root EBS volume, so data at rest may be stored unencrypted depending on the source AMI and account defaults."
    }
  ],
  "patched_code": "resource \"aws_launch_configuration\" \"lc\" {\n  name          = \"test_ecs\"\n  image_id      = data.aws_ami.amazon_linux.id\n  instance_type = \"t2.micro\"\n  lifecycle {\n    create_before_destroy = true\n  }\n  iam_instance_profile        = aws_iam_instance_profile.ecs_service_role.name\n  key_name                    = var.key_name\n  security_groups             = [aws_security_group.ec2-sg.id]\n  associate_public_ip_address = false\n\n  metadata_options {\n    http_endpoint = \"enabled\"\n    http_tokens   = \"required\"\n  }\n\n  root_block_device {\n    encrypted = true\n  }\n\n  user_data = <<EOF\nsudo apt-get update\nsudo echo \"ECS_CLUSTER=${var.cluster_name}\" >> /etc/ecs/ecs.config\nEOF\n}\n",
  "fix_summary": "Disabled automatic public IP assignment, enforced IMDSv2, and enabled encryption for the root EBS volume."
}
